+// Build the deterministic document id for a (date, sourceWorkoutId) pair.
+export function sorenessDocId(date, sourceWorkoutId) {
+  return sourceWorkoutId ? `soreness-${date}-${sourceWorkoutId}` : `soreness-${date}`;
+}
