+  for (const t of tracks.values()) {
+    t.dates = [...t.levels.keys()].sort();
+    t.startDate = t.dates[0];
+    t.endDate = t.dates[t.dates.length - 1];
+    t.peak = Math.max(...t.levels.values());
+    t.lastLevel = t.levels.get(t.endDate);
