+ * Returns { tracks (each with .lane), laneCount }.
+ */
+export function packLanes(tracks) {
+  const sorted = [...tracks].sort(
+    (a, b) =>
+      a.startDate.localeCompare(b.startDate) ||
+      b.endDate.localeCompare(a.endDate) ||
+      a.key.localeCompare(b.key),
+  );
